{"content": """"Generated tests for webhook signature verification."""
import hashlib
import hmac

from app.webhooks.signature import signature_matches


def _expected(secret: str, payload: bytes) -> str:
    return hmac.new(
        secret.encode(), payload, hashlib.sha256
    ).hexdigest()


def test_valid_signature_matches():
    payload = b'{"order": 1}'
    assert (
        signature_matches("s3cret", payload, _expected("s3cret", payload))
        is True
    )


def test_wrong_secret_fails():
    payload = b'{"order": 1}'
    assert (
        signature_matches("s3cret", payload, _expected("other", payload))
        is False
    )


def test_short_hex_is_false_not_error():
    assert signature_matches("s3cret", b"x", "abcd") is False
", "framework": "pytest", "path": "workflo_generated_tests/test_signature_matches.py", "rationale": "Verifies the HMAC contract, mismatch detection, and the fail-closed handling of malformed hex."}
